package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
class ApplicationInstanceHeartbeatMigrationContractTest{
 private static final Path MIGRATION=Path.of("..","docs","sql","2026-09-29_application_instance_heartbeat_phase5b.sql"),VERIFY=Path.of("..","docs","sql","verification","2026-09-29_application_instance_heartbeat_phase5b_verification.sql");
 @Test void migrationIsAdditiveNullableRerunnableAndDoesNotRewriteOldRows()throws Exception{String s=Files.readString(MIGRATION);for(String token:new String[]{"COL_LENGTH(N'dbo.ApplicationInstances',N'LastHeartbeatAt') IS NULL","LastHeartbeatAt datetime2(7) NULL","LastHumanActivityAt datetime2(7) NULL","BEGIN TRANSACTION","ROLLBACK TRANSACTION","THROW;","No backfill"})assertTrue(s.contains(token),token);for(String forbidden:new String[]{" DROP "," NOT NULL;","UPDATE dbo.ApplicationInstances","CREATE INDEX","ALTER SECURITY POLICY"})assertFalse(s.contains(forbidden),forbidden);}
 @Test void verifierProtectsOldClientInsertAndOriginalRlsContracts()throws Exception{String s=Files.readString(VERIFY);for(String token:new String[]{"OldClientInsertLeavesHeartbeatNull","INSERT dbo.ApplicationInstances(ShaleClientId,UserId,MachineId,ClientType,MajorVersion,MinorVersion,BuildVersion)","StrictRlsPredicateCount","FilterPredicate","InsertBlockPredicate","UpdateBlockPredicate","NoOverlayPredicate","OriginalPhase4BColumns","OriginalPrimaryKey","OriginalForeignKeys","OriginalChecks","NoForcedBackfillOrDefault","PriorPhaseTables"})assertTrue(s.contains(token),token);assertFalse(s.contains("TRY"));}
}
